arch(280,300,'#acd4df');label('KÖYE DÖN · E',280,175,'#e3f3d7',12);drawLandmarks();let objects=trees.filter(t=>t.x>camera.x-60&&t.x<camera.x+VIEW.w+60&&t.y>camera.y-30&&t.y<camera.y+VIEW.h+110).map(t=>({y:t.y,draw:()=>{ctx.save();if([p,...enemies.filter(e=>!e.dead)].some(e=>Math.abs(e.x-t.x)<48&&e.y<t.y+12&&e.y>t.y-105))ctx.globalAlpha=.18;tree(t);ctx.restore()}}));enemies.forEach(e=>{if(e.dead||e.x<camera.x-50||e.x>camera.x+VIEW.w+50||e.y<camera.y-50||e.y>camera.y+VIEW.h+80)return;objects.push({y:e.y,draw:()=>{if(e.boss){drawBoss(e);return}if(e.rank>1){drawCreature(e);return}shadow(e.x,e.y,23);ctx.strokeStyle=['#dbed9b','#ffe1a0','#9ee7e9','#e1b8f4'][e.rank-1]||'#dbed9b';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(e.x,e.y,25,10,0,0,7);ctx.stroke();let b=Math.round(Math.sin(time*4+e.phase)*2);rect(e.x-17,e.y-18+b,34,15,['#89bb65','#c3a551','#61aaa5','#a784bd'][e.rank-1]||'#89bb65');rect(e.x-13,e.y-25+b,26,9,'#8cbd7b');rect(e.x-20,e.y-12+b,40,10,['#89bb65','#c3a551','#61aaa5','#a784bd'][e.rank-1]||'#89bb65');rect(e.x-16,e.y-6+b,32,5,'#427753');rect(e.x-9,e.y-17+b,4,5,'#243b30');rect(e.x+6,e.y-17+b,4,5,'#243b30');rect(e.x-10,e.y-23+b,7,3,'#b6d890');if(e.hit>0){ctx.fillStyle='#fff7';ctx.fillRect(e.x-17,e.y-23,34,23)}label('SLIME · Sv.'+(e.rank||1),e.x,e.y-47,'#f0f3cd',9);rect(e.x-18,e.y-37,36,4,'#15251d');rect(e.x-18,e.y-37,36*e.hp/e.max,3,'#c4db84')}})});objects.push({y:p.y,draw:()=>{person(p.x,p.y);label('GEZGİN',p.x,p.y-82,'#eef2dc',9);}});objects.sort((a,b)=>a.y-b.y).forEach(o=>o.draw());particles.forEach(q=>label(q.text,q.x,q.y-(1.2-q.life)*24,q.color,11));
