function update(dt){if(p.area==='hub'){updateHub(dt);return}time+=dt;$('interactHint').hidden=false;$('interactHint').textContent=Math.hypot(p.x-280,p.y-330)<100?'E · Ocak Köyü’ne dön':'';if(!modalOpen()){let dx=Number(!!(keys.d||keys.arrowright))-Number(!!(keys.a||keys.arrowleft)),dy=Number(!!(keys.s||keys.arrowdown))-Number(!!(keys.w||keys.arrowup));let length=Math.hypot(dx,dy)||1,speed=185*sprintMultiplier*(p.boost==='speed'?1.15:1)*(activeSwing?.4:1);let nx=Math.max(20,Math.min(WORLD.w-24,p.x+dx/length*speed*dt)),ny=Math.max(70,Math.min(WORLD.h-24,p.y+dy/length*speed*dt));if(!blocked(nx,p.y))p.x=nx;if(!blocked(p.x,ny))p.y=ny;enemies.forEach(e=>{if(p.area==='hub')return;if(e.dead){e.dead-=dt;if(e.dead<=0){let pos=e.boss?{x:e.homeX,y:e.homeY}:spawnPoint(e.zone);e.x=pos.x;e.y=pos.y;e.homeX=pos.x;e.homeY=pos.y;e.hp=e.max;e.dead=0;e.slow=0;e.burnTicks=0}return}e.hit=Math.max(0,e.hit-dt);let d=Math.hypot(e.x-p.x,e.y-p.y);if(d<190&&d>28&&p.x>270){e.x+=(p.x-e.x)/d*34*(e.slow>0?.6:1)*dt;e.y+=(p.y-e.y)/d*34*(e.slow>0?.6:1)*dt}else if(d>=190){e.x+=(e.homeX+Math.sin(time*.6+e.phase)*35-e.x)*dt;e.y+=(e.homeY+Math.cos(time*.5+e.phase)*25-e.y)*dt}if(!e.boss&&d<32&&hitCooldown<=0){p.hp-=Math.max(1,(e.boss?18:8)+(e.rank||1)*2-p.armor*2-(accessoryStats().armor||0));hitCooldown=.85;tone(100);particles.push({x:p.x,y:p.y-38,text:'-'+Math.max(1,(e.boss?18:8)+(e.rank||1)*2-p.armor*2-(accessoryStats().armor||0)),color:'#efaa94',life:.8});if(p.hp<=0){p.hp=p.maxHp;returnVillage();toast('Mira seni kurtardı. Köye geri döndün.');log('Köyde yeniden doğdun.')}ui();save()}})}cooldown=Math.max(0,cooldown-dt);swing=Math.max(0,swing-dt);hitCooldown=Math.max(0,hitCooldown-dt);particles.forEach(q=>q.life-=dt);particles=particles.filter(q=>q.life>0);$('toast').style.opacity=time<toastUntil?1:0;$('coords').textContent=Math.round(p.x)+', '+Math.round(p.y);if(p.area==='hub'){updateHub(0);return}const z=zoneAt(p.x,p.y);if(currentZone!==z.name){currentZone=z.name;document.querySelector('.zone span').innerHTML=z.name.toLocaleUpperCase('tr')+'<small>'+z.level+' · Keşif bölgesi</small>';document.querySelector('.game-bottom>span>span').textContent=' / '+z.name;toast(z.name+' · '+z.level);log(z.name+' keşfedildi.')}if(Math.floor(time/3)!==Math.floor((time-dt)/3))save()}function frame(t){let dt=Math.min((t-last)/1000,.05);last=t;const beforeX=p.x,beforeY=p.y;tickWeapons(dt);update(dt);updateMotion(dt,p.x-beforeX,p.y-beforeY);draw();drawHeroPreview();requestAnimationFrame(frame)}ui();log('Ocak Köyü’ne hoş geldin.');

function drawLandmarks(){for(const z of zones){if(!z.x&&!z.y)continue;const x=z.x+830,y=z.y+520;if(x<camera.x-250||x>camera.x+1200||y<camera.y-200||y>camera.y+840)continue;rect(x-115,y-80,230,150,'#7c816044');for(let i=0;i<4;i++){let cx=x-100+i*65;shadow(cx,y+40,18);rect(cx-12,y-80,24,120,'#747e78');rect(cx-16,y-85,32,10,'#a4ad95');rect(cx-16,y+32,32,10,'#a4ad95');rect(cx-6,y-70,5,95,'#929c89')}rect(x-45,y-20,90,48,'#686e66');rect(x-35,y-27,70,8,'#a3b298');label(z.name.toLocaleUpperCase('tr'),x,y-110,'#f4e6b4',14);label(z.level+' · Kadim geçit',x,y+75,'#d8ddc4',11)}for(let x=1000;x<WORLD.w;x+=850){let y=pathY(x);rect(x,y-62,5,55,'#69583c');rect(x-29,y-67,64,22,'#ac9c6b');label('DOĞU →',x+2,y-52,'#283d2b',9)}}


